# Generated by ReLife JavaScript. Run: Rscript index.R binary-file
args <- commandArgs(trailingOnly=TRUE)
if (length(args) != 1L) stop("Usage: Rscript index.R binary-file")
bytes <- readBin(args[[1]], "raw", n=file.info(args[[1]])$size)
counts <- tabulate(as.integer(bytes)+1L, nbins=256L)
p <- counts[counts > 0L] / length(bytes)
cat(sprintf("bytes=%d\nentropy=%.6f\n", length(bytes), -sum(p * log2(p))))
